 if(stage==-1){for(int x=69;x<=72;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);p.teleportTo(l,Q.getX()+.5,Q.getY(),Q.getZ()-4.5,Set.of(),0,0,true);stage=0;due=now+60;return;}
 if(stage==0&&now>=due){knowledge(p);p.setGameMode(GameType.SURVIVAL);p.getInventory().clearContent();for(int x=69;x<=72;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);for(var ent:l.getEntitiesOfClass(LivingEntity.class,new AABB(Q).inflate(40)))if(!(ent instanceof net.minecraft.world.entity.player.Player))ent.discard();for(var ent:l.getEntitiesOfClass(ItemEntity.class,new AABB(Q).inflate(40)))ent.discard();for(var q:BlockPos.betweenClosed(Q.offset(-8,0,-6),Q.offset(24,6,6)))l.setBlockAndUpdate(q,Blocks.AIR.defaultBlockState());for(var q:BlockPos.betweenClosed(Q.offset(-8,-1,-6),Q.offset(24,-1,6)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());p.teleportTo(l,Q.getX()+.5,Q.getY(),Q.getZ()-4.5,Set.of(),0,0,true);source=GolemProbe.seal(p,SealKind.PICKUP,Q.east(4).south(2));dest=LogisticsClient.chestSeal(p,SealKind.FILL,Q.east(9));out=(ChestBlockEntity)l.getBlockEntity(dest.support());g=spawn(p,GolemDesign.BASIC,GolemProgress.EMPTY);l.addFreshEntity(new ItemEntity(l,Q.getX()+4.5,Q.getY()+.1,Q.getZ()+.5,new ItemStack(Items.EMERALD,17)));stage=1;due=now+450;return;}
 if(stage==1){check(now<due,"Clockwork route timeout");if(GolemClient.count(out,Items.EMERALD)!=17)return;progress(0,0);g.discard();out.clearContent();g=spawn(p,new GolemDesign(3,1,0,0),new GolemProgress(0,999));g.setHealth(7);l.addFreshEntity(new ItemEntity(l,Q.getX()+4.5,Q.getY()+.1,Q.getZ()+.5,new ItemStack(Items.EMERALD,17)));stage=2;due=now+500;Thaumcraft.LOGGER.info("RANK_CLOCKWORK_OK: real pickup and delivery grant no XP to ordinary head");return;}
 if(stage==2){check(now<due,"Smart route timeout "+g.position());if(GolemClient.count(out,Items.EMERALD)!=17)return;progress(1,1);check(g.getHealth()==7&&g.getMaxHealth()==17&&Math.abs(g.getAttributeValue(Attributes.MOVEMENT_SPEED)-g.design().speed()*1.025)<.000001,"First promotion healed or lacked bonuses");GolemClient.remove(source);source=LogisticsClient.chestSeal(p,SealKind.EMPTY,Q.west(5));in=(ChestBlockEntity)l.getBlockEntity(source.support());in.setItem(0,new ItemStack(Items.DIAMOND,13));l.setBlockAndUpdate(source.getBlockPos().north(),Blocks.REDSTONE_BLOCK.defaultBlockState());stage=3;due=now+60;Thaumcraft.LOGGER.info("RANK_PROMOTION_OK: real pickup/delivery crossed 1000 XP exactly once, leftover XP and no healing");return;}
 if(stage==3&&now>=due){progress(1,1);check(GolemClient.count(in,Items.DIAMOND)==13,"Paused route moved cargo");l.removeBlock(source.getBlockPos().north(),false);stage=4;due=now+600;return;}
 if(stage==4){check(now<due,"Empty/fill route timeout");if(GolemClient.count(out,Items.DIAMOND)!=13)return;progress(1,3);stage=5;due=now+70;return;}
 if(stage==5&&now>=due){progress(1,3);cleanup(l);g.discard();g=spawn(p,new GolemDesign(1,1,3,0),new GolemProgress(1,3));source=GolemProbe.seal(p,SealKind.BREAKER,Q.east(4).above());l.setBlockAndUpdate(Q.east(4),Blocks.STONE.defaultBlockState());denyBreak=true;stage=6;due=now+80;Thaumcraft.LOGGER.info("RANK_TRANSFER_OK: exact extraction/delivery XP; redstone and idle ticks grant none");return;}
 if(stage==6&&now>=due){progress(1,3);check(l.getBlockState(Q.east(4)).is(Blocks.STONE)&&g.cargo.isEmpty(),"Canceled break changed world");denyBreak=false;stage=7;due=now+350;return;}
 if(stage==7){check(now<due,"Rank breaker timeout");if(!l.isEmptyBlock(Q.east(4)))return;progress(1,4);check(g.cargo.getItem(0).is(Items.COBBLESTONE),"Successful rank break loot invalid");cleanup(l);g.dropCargo(l);g.discard();g=spawn(p,new GolemDesign(3,1,1,0),new GolemProgress(1,4));source=LogisticsClient.chestSeal(p,SealKind.PROVIDER,Q.west(5));in=(ChestBlockEntity)l.getBlockEntity(source.support());in.setItem(0,new ItemStack(Items.EMERALD,8));dest=LogisticsClient.chestSeal(p,SealKind.STOCK,Q.east(9));out=(ChestBlockEntity)l.getBlockEntity(dest.support());dest.sample(0,new ItemStack(Items.EMERALD));dest.amounts[0]=8;stage=20;due=now+600;Thaumcraft.LOGGER.info("RANK_BREAK_OK: denied Forge break gives no XP; actual stone break grants exactly one");return;}
 if(stage==20){check(now<due,"Rank provider/stock timeout "+g.position());if(GolemClient.count(out,Items.EMERALD)!=8)return;progress(1,6);check(in.isEmpty()&&g.cargo.isEmpty(),"Rank provider duplicated cargo");cleanup(l);source=GolemProbe.seal(p,SealKind.HARVEST,Q.east(4).south(2));l.setBlockAndUpdate(Q.east(4).below(),Blocks.FARMLAND.defaultBlockState());l.setBlockAndUpdate(Q.east(4),((CropBlock)Blocks.WHEAT).getStateForAge(7));stage=21;due=now+400;Thaumcraft.LOGGER.info("RANK_STOCK_OK: provider fetch and stock delivery award one each for eight real items");return;}
 if(stage==21){check(now<due,"Rank harvest timeout");if(l.getBlockState(Q.east(4)).getValue(CropBlock.AGE)==7)return;progress(1,7);check(!g.cargo.isEmpty(),"Rank crop has no physical drops");cleanup(l);source=GolemProbe.seal(p,SealKind.USE,Q.east(6).above());source.useEmpty=true;l.setBlockAndUpdate(source.support(),Blocks.LEVER.defaultBlockState().setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.ATTACH_FACE,net.minecraft.world.level.block.state.properties.AttachFace.FLOOR));stage=22;due=now+400;return;}
 if(stage==22){check(now<due,"Rank Use timeout "+g.position());if(!l.getBlockState(source.support()).getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.POWERED))return;progress(1,8);cleanup(l);g.dropCargo(l);g.discard();g=spawn(p,new GolemDesign(1,1,3,0),new GolemProgress(1,8));source=GolemProbe.seal(p,SealKind.LUMBER,Q.east().south(2));source.radius=6;for(int n=0;n<3;n++)l.setBlockAndUpdate(Q.east(4).above(n),Blocks.OAK_LOG.defaultBlockState());stage=23;due=now+500;Thaumcraft.LOGGER.info("RANK_HARVEST_USE_OK: replanted crop and real empty-hand lever interaction award one each");return;}
 if(stage==23){check(now<due,"Rank lumber timeout "+g.position());if(l.getBlockState(Q.east(4)).is(Blocks.OAK_LOG))return;progress(1,11);check(g.cargo.getItem(0).is(Items.OAK_LOG)&&g.cargo.getItem(0).getCount()==3,"Lumber XP did not match three physical logs");cleanup(l);g.dropCargo(l);g.discard();g=spawn(p,new GolemDesign(3,1,2,0),new GolemProgress(1,11));source=GolemProbe.seal(p,SealKind.GUARD,Q.east(4).south(2));victim=BatRiftClient.mob(p,Vec3.atBottomCenterOf(Q.east(4)));victim.setHealth(1);stage=24;due=now+400;Thaumcraft.LOGGER.info("RANK_LUMBER_OK: three connected logs grant exactly three XP");return;}
 if(stage==24){check(now<due,"Rank melee cancellation timeout");if(meleeCanceled<2)return;progress(1,11);check(victim.getHealth()==1,"Canceled melee did damage");denyMelee=false;stage=25;due=now+400;return;}
 if(stage==25){check(now<due,"Rank melee kill timeout");if(victim.isAlive())return;progress(1,20);check(g.attackDamage()==5.25F,"Melee fighter rank bonus missing");cleanup(l);g.discard();combat(p,now);Thaumcraft.LOGGER.info("RANK_MELEE_OK: canceled melee grants none, actual kill grants one plus eight; attack attribute includes rank bonus");return;}
 if(stage==8){check(now<due,"Rank canceled dart timeout "+g.position());if(canceled<2)return;progress(9,99991);check(victim.getHealth()==1,"Canceled rank dart caused damage");denyDamage=false;stage=9;due=now+500;Thaumcraft.LOGGER.info("RANK_CANCEL_OK: two physical dart impacts canceled by Forge give no XP");return;}
 if(stage==9){check(now<due,"Rank dart kill timeout");if(victim.isAlive())return;progress(10,0);check(g.getHealth()==4&&g.getMaxHealth()==26&&g.attackDamage()==5.5F,"Rank ten combat bonus/heal invalid");cleanup(l);g.setMode(2);g.cargo.setItem(0,new ItemStack(Items.GOLD_INGOT,11));p.setItemInHand(InteractionHand.MAIN_HAND,item("golem_bell"));p.setShiftKeyDown(true);check(g.interact(p,InteractionHand.MAIN_HAND,Vec3.ZERO)==InteractionResult.SUCCESS&&g.isRemoved(),"Veteran packing failed");p.setShiftKeyDown(false);int slot=java.util.stream.IntStream.range(0,36).filter(n->p.getInventory().getItem(n).getItem() instanceof GolemPlacer).findFirst().orElseThrow();packed=p.getInventory().removeItemNoUpdate(slot);check(packed.get(GolemContent.PROGRESS.get()).equals(new GolemProgress(10,0))&&Math.abs(packed.get(GolemContent.HEALTH.get())-4F/26)<.00001&&packed.getHoverName().getString().equals("Golem veteran"),"Packed progress/name/health lost");check(l.getEntitiesOfClass(ItemEntity.class,new AABB(g.blockPosition()).inflate(3),v->v.getItem().is(Items.GOLD_INGOT)&&v.getItem().getCount()==11).size()==1,"Veteran cargo duplicated/lost");var o=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,l.registryAccess());o.store("packed",ItemStack.CODEC,packed);packed=TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),o.buildResult()).read("packed",ItemStack.CODEC).orElseThrow();p.setItemInHand(InteractionHand.MAIN_HAND,packed);stage=10;due=now+80;Thaumcraft.LOGGER.info("RANK_KILL_PACK_OK: real dart kill gives one plus eight XP, reaches ten, no healing; packed components and eleven physical cargo retained");return;}
 if(stage==10&&now>=due){var at=Q.east(2);var result=packed.getItem().useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at.below()),Direction.UP,at.below(),false)));check(result==InteractionResult.SUCCESS&&packed.isEmpty(),"Packed veteran deployment failed");g=spawned;check(g!=null&&g.progress().rank()==10,"Redeployed veteran join missing");g.setMode(2);check(Math.abs(g.getHealth()-4)<.00001&&g.getMaxHealth()==26&&g.getCustomName().getString().equals("Golem veteran")&&g.progress().xp()==0,"Veteran redeploy healed/lost progression");g.addRankXp(Integer.MAX_VALUE);progress(10,0);p.setItemInHand(InteractionHand.MAIN_HAND,item("golem_bell"));check(g.interact(p,InteractionHand.MAIN_HAND,Vec3.ZERO)==InteractionResult.SUCCESS,"Rank bell overlay failed");g.setMode(2);stage=11;Thaumcraft.LOGGER.info("RANK_CLIENT_OK: native XP, threshold, attributes, denied operations, physical combat, packed item serialization and redeployment");}
